94	    selectedCommentNames.value = [];
95	  }
96	};
97	
98	const isSelection = (comment: ListedComment) => {
99	  return selectedCommentNames.value.includes(comment.comment.metadata.name);
100	};
101	
102	watch(
103	  () => selectedCommentNames.value,
104	  (newValue) => {
105	    checkAll.value = newValue.length === comments.value?.items.length;
106	  }
107	);
108	
